buggy.strings_pad_null_stringdtype:
import numpy as np
from numpy.dtypes import StringDType

arr = np.array(["a", None], dtype=StringDType())
names = ["center", "ljust", "rjust", "zfill"]

missing = 0
raised = 0
null_length_errors = 0
null_preserved = 0
for name in names:
    fn = getattr(np.strings, name, None)
    if fn is None:
        missing += 1
        continue
    try:
        res = fn(arr, 3)
    except Exception as exc:
        raised += 1
        if "null string" in str(exc):
            null_length_errors += 1
        continue
    try:
        if res[1] is None:
            null_preserved += 1
    except Exception:
        pass

probe("padding_ufuncs_missing", float(missing))
probe("padding_ufuncs_raised", float(raised))
probe("padding_ufuncs_null_length_errors", float(null_length_errors))
probe("padding_ufuncs_null_preserved", float(null_preserved))

